df = pd.read_csv('data.csv')
sub = df[df['account_id']=='YxSxqn0'].copy()

# check day-of-week pattern
import datetime
def dow(d):
    m,dd,y = d.split('/')
    return datetime.date(int(y),int(m),int(dd)).weekday()
tot = sub.groupby('date')['unblended_cost'].sum()
